# Generated by `shiny theme new` from shiny-mountain.jpg
# Base scheme: Rosé Pine — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Rosé Pine"
GHOSTTY_THEME="Rose Pine"   # built-in: ghostty +list-themes
ACCENT_PRESET=4                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#191724"         # window background
BG_DARK="#141220"    # frames, omnibox
SURFACE="#26233A"    # borders, dividers, inactive window border
SELECTION="#363F4C"  # selected rows, text selection
MUTED="#524F67"      # shortcuts, scrollbar
COMMENT="#6E6A86"    # subtext, inactive tabs
FG="#E0DEF4"         # primary text
FG_DIM="#908CAA"     # secondary text
ACCENT="#9CCFD8"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#F6C177"    # secondary accent: cursor, shortcuts, search selection
